async function operatorAuth(request,response){const {authenticate,hasRole}=require('../security/http-security');const auth=authenticate(request,{apiToken:process.env.API_BEARER_TOKEN||null,authSecret:process.env.FORGE_AUTH_SIGNING_SECRET||null,staticActor:process.env.FORGE_STATIC_ACTOR_ID||null,staticTenant:process.env.FORGE_STATIC_TENANT_ID||null});if(!auth||!hasRole(auth,'OWNER')){response.statusCode=403;response.setHeader('content-type','application/json');response.end(JSON.stringify({error:{code:'FORBIDDEN'}}));return null}return auth}
